import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt'}
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def generate_job_id(filename):
    return hashlib.sha256(f"{filename}{time.time()}{os.getpid()}".encode()).hexdigest()[:16]

def sanitize_metadata(metadata):
    """Remove potentially dangerous characters from metadata fields"""
    dangerous = ['<', '>', '&', '"', "'"]
    for char in dangerous:
        metadata = metadata.replace(char, '')
    return metadata

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.3'})

@app.route('/convert', methods=['POST'])
def convert_document():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 415

    # Check file size
    file.seek(0, 2)
    size = file.tell()
    file.seek(0)
    if size > MAX_FILE_SIZE:
        return jsonify({'error': 'File too large'}), 413

    output_format = request.form.get('format', 'pdf')
    title_override = request.form.get('title', '')

    # Sanitize the title metadata
    if title_override:
        title_override = sanitize_metadata(title_override)

    job_id = generate_job_id(file.filename)
    job_dir = os.path.join(UPLOAD_DIR, job_id)
    os.makedirs(job_dir, exist_ok=True)

    safe_name = secure_filename(file.filename)
    input_path = os.path.join(job_dir, safe_name)
    file.save(input_path)

    output_filename = os.path.splitext(safe_name)[0] + '.' + output_format
    output_path = os.path.join(job_dir, output_filename)

    # Build LibreOffice conversion command
    cmd = f'libreoffice --headless --convert-to {output_format}'

    if title_override:
        # Set document title via macro parameter
        cmd += f' --infilter="writer_pdf_Export" -env:UserInstallation=file:///tmp/.lo_{job_id}'
        cmd += f' --pidfile /tmp/.lo_{job_id}.pid'

    cmd += f' --outdir {job_dir} {input_path}'

    # Apply post-processing with exiftool for metadata
    post_cmd = None
    if title_override and output_format == 'pdf':
        post_cmd = f'exiftool -Title="{title_override}" {output_path}'

    try:
        result = subprocess.run(cmd, shell=True, capture_output=True, 
                              timeout=60, cwd=job_dir)
        if result.returncode != 0:
            return jsonify({'error': 'Conversion failed', 
                          'details': result.stderr.decode()[:200]}), 500

        if post_cmd:
            post_result = subprocess.run(post_cmd, shell=True, 
                                        capture_output=True, timeout=30)
            if post_result.returncode != 0:
                app.logger.warning(f'Metadata update failed for {job_id}')

        if not os.path.exists(output_path):
            return jsonify({'error': 'Output file not generated'}), 500

        return send_file(output_path, as_attachment=True, 
                        download_name=output_filename)
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    except Exception as e:
        app.logger.error(f'Conversion error: {str(e)}')
        return jsonify({'error': 'Internal error'}), 500
    finally:
        # Cleanup handled by cron job
        pass

@app.route('/batch', methods=['POST'])
def batch_convert():
    """Batch conversion endpoint - accepts JSON with URLs"""
    return jsonify({'error': 'Batch endpoint temporarily disabled'}), 503

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080, debug=False)
